import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.B0hSrcZ6.js";const o="/info/05-computer.webp",r="/info/05-computer-s3.webp",l="/info/05-computer-s5.webp",i="/info/05-computer-s6.webp",p="/info/05-computer-s7.webp",f=JSON.parse('{"title":"第 5 章 共享云电脑：文件、浏览器与接管","description":"本章解析 Grok Bot 共享云电脑的机制，讲解屏幕监控与浏览器安全接管。指导读者规范多端文件交接与网络出口，借助服务总账与恢复脚本应对系统重置风险。","frontmatter":{},"headers":[],"relativePath":"part1/05-computer.md","filePath":"part1/05-computer.md","lastUpdated":1792210948000}'),c={name:"part1/05-computer.md"};function d(h,a,g,u,b,k){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="第-5-章-共享云电脑-文件、浏览器与接管" tabindex="-1">第 5 章 共享云电脑：文件、浏览器与接管 <a class="header-anchor" href="#第-5-章-共享云电脑-文件、浏览器与接管" aria-label="Permalink to &quot;第 5 章 共享云电脑：文件、浏览器与接管&quot;">​</a></h1><p>刚接触 Grok Bot 的用户通常会产生几个常见误解。这些误区往往会导致后续开发和维护遇到障碍：</p><ul><li>误以为新建一个 Bot 就会多出一台独立的虚拟机。</li><li>误以为让几个 Bot 一起干活时，它们能直接读懂对方的聊天记录。</li><li>在需要第三方工具登录时，直接把账号密码甚至 API Token 贴进聊天窗口。</li></ul><p>等到云电脑因为系统维护或底层更新突然清空，安装好的环境和脚本全没了。此时大家才发现自己对这台云电脑的底层机制一无所知。</p><p>同一账号下的所有 Bot 都在同一台云端计算机上工作，共享同一个磁盘与文件系统。它们看不见彼此的会话记录，协作全靠磁盘上的文件流转。</p><p>遇到登录验证时，正确的做法是直接在云端浏览器接管屏幕输入凭据，而不是把密码交给模型。同时这台云电脑本质上是一个随时可能被重新构建的临时容器，平台底层更新或管理员执行维护时，手动安装的软件包都会丢失。</p><p>这一章带你拆解这台云电脑的真实工作方式。你将学会怎样在多 Bot 之间安全交接文件与屏幕、如何通过本地桌面路由网络流量以应对白名单限制，以及如何用一套轻量标准化的备份流水线，让整个环境在经历重置后能够有条不紊地快速恢复。</p><p><img src="'+o+'" alt="共享云电脑：文件、浏览器与接管" width="1600" height="1013" decoding="async"></p><h2 id="共享电脑的底层机制-一台机器与多个-bot" tabindex="-1">共享电脑的底层机制：一台机器与多个 Bot <a class="header-anchor" href="#共享电脑的底层机制-一台机器与多个-bot" aria-label="Permalink to &quot;共享电脑的底层机制：一台机器与多个 Bot&quot;">​</a></h2><p><strong>你账号下的所有 Bot 共用同一台托管 Linux 电脑。</strong> 无论切到哪个 Bot，面对的都是同一个 <code>/workspace</code> 根目录和持久磁盘。</p><p>聊天记录独立保存在外部，即使在机器里执行 <code>rm -rf</code> 删空或系统崩溃重启，对话与列表依然都在。</p><p><strong>新建 Bot 不等于安全隔离。</strong> 任何 Bot 只要拿到命令行权限，就能读写 <code>/workspace</code> 里的所有数据，千万别在里面放未经加密的敏感信息。</p><p>版本演进：</p><ul><li>v0.68.0：支持在设置中移除其他电脑</li><li>v0.68.1（2026-10-07 发布）：屏幕分辨率从 1280×800 升到 1920×1200，操作与截图响应更快</li><li>v0.70.2：增加专属邮箱，支持网页直接存为 PDF</li></ul><p>底层细节可看 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">《4.6 虚拟机、记忆与备份》</a>。</p><h2 id="多-bot-屏幕与工作状态监控" tabindex="-1">多 Bot 屏幕与工作状态监控 <a class="header-anchor" href="#多-bot-屏幕与工作状态监控" aria-label="Permalink to &quot;多 Bot 屏幕与工作状态监控&quot;">​</a></h2><h3 id="状态与配置" tabindex="-1">状态与配置 <a class="header-anchor" href="#状态与配置" aria-label="Permalink to &quot;状态与配置&quot;">​</a></h3><p><strong>侧边栏常驻三类状态</strong>。</p><ul><li>需关注：等回答、审批或交接。</li><li>未读活动：已完成任务，等看结果。</li><li>工作状态：正在跑脚本、抓网页或调工具。</li></ul><p>点顶部名称进「查看对话详情」，可改当前 Bot 的名称、标签与头像。个人 Bot 没单独描述框，<strong>直接发消息</strong>就能调定位。</p><h3 id="监控与通知" tabindex="-1">监控与通知 <a class="header-anchor" href="#监控与通知" aria-label="Permalink to &quot;监控与通知&quot;">​</a></h3><p>云端操作支持<strong>实时看屏幕</strong>。</p><p><strong>处于焦点时通知自动抑制</strong>，只在侧边栏和 Dock 标未读；离线可在配置文件开通知，推送到桌面或手机。</p><h2 id="浏览器接管-移交屏幕-不交密码" tabindex="-1">浏览器接管：移交屏幕，不交密码 <a class="header-anchor" href="#浏览器接管-移交屏幕-不交密码" aria-label="Permalink to &quot;浏览器接管：移交屏幕，不交密码&quot;">​</a></h2><p><img src="'+r+'" alt="浏览器接管：移交屏幕，不交密码" width="1600" height="1013" loading="lazy" decoding="async"></p><p>别把账密发进聊天框。你和 Bot 共用浏览器，<strong>移交屏幕，不交密码</strong>。</p><h3 id="接管步骤" tabindex="-1">接管步骤 <a class="header-anchor" href="#接管步骤" aria-label="Permalink to &quot;接管步骤&quot;">​</a></h3><ol><li>触发暂停：Bot 打开登录页，遇账密、扫码或 2FA 时暂停。</li><li>接管输入：点击全屏接管键鼠。</li><li>人工登录：自填账密或扫码验证。</li><li>移交执行：<strong>登录后通知 Bot 复用 Cookie 运行</strong>，碰不到明文密码。</li></ol><h3 id="审批闸门" tabindex="-1">审批闸门 <a class="header-anchor" href="#审批闸门" aria-label="Permalink to &quot;审批闸门&quot;">​</a></h3><p>按 <code>Cmd+,</code> 在「常规」-「Bot」设置。</p><ul><li><strong>规则冲突以「先询问」（Ask first）为准</strong>。</li><li>企业规则显示 <code>Required by your admin. You can&#39;t edit or delete this rule.</code> 无法修改。</li><li>v0.70.2 强化了发信与发帖、支付以及改生产环境前的确认。</li></ul><p>详见 <a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">设置和通知</a>。</p><h2 id="多-bot-文件交接约定与目录规划" tabindex="-1">多 Bot 文件交接约定与目录规划 <a class="header-anchor" href="#多-bot-文件交接约定与目录规划" aria-label="Permalink to &quot;多 Bot 文件交接约定与目录规划&quot;">​</a></h2><h3 id="文件协作模式" tabindex="-1">文件协作模式 <a class="header-anchor" href="#文件协作模式" aria-label="Permalink to &quot;文件协作模式&quot;">​</a></h3><p>Bot 间读不了聊天记录，<strong>多 Bot 协作的唯一通道是共享磁盘文件</strong>。</p><p>提示词只需传入上一棒文件路径，详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">《4.6 虚拟机、记忆与备份》</a>。</p><ol><li>整理员抓取生成 <code>tweets.md</code></li><li>分析师提炼输出 <code>profile.md</code></li><li>设计师依画像生成 <code>design.md</code></li><li>工程师读设计构建代码</li></ol><h3 id="目录规划" tabindex="-1">目录规划 <a class="header-anchor" href="#目录规划" aria-label="Permalink to &quot;目录规划&quot;">​</a></h3><p>建机之初定好目录，免得多 Bot 把文件写乱。</p><table tabindex="0"><thead><tr><th>目录路径</th><th>存放内容</th><th>写入规范</th></tr></thead><tbody><tr><td><code>/workspace/handoff/</code></td><td>中间产物</td><td>统一 Markdown 或 JSON，带任务前缀</td></tr><tr><td><code>/workspace/projects/</code></td><td>项目代码与资产</td><td>按项目分独立子目录，关联 Git 仓库</td></tr><tr><td><code>/workspace/tools/</code></td><td>本地自写脚本</td><td>仅留无密钥源码，排查后同步备份仓</td></tr><tr><td><code>~/.env</code> 或本地文件</td><td>API 密钥</td><td>仅保存在本地，<strong>严禁提交代码仓或在会话打印</strong></td></tr></tbody></table><h3 id="磁盘清理与-disk-saver" tabindex="-1">磁盘清理与 Disk Saver <a class="header-anchor" href="#磁盘清理与-disk-saver" aria-label="Permalink to &quot;磁盘清理与 Disk Saver&quot;">​</a></h3><p>系统报 <code>Computer is low on disk space</code> 或 <code>Computer is critically low on disk space</code> 警告，去侧边栏点 <strong>Disk Saver</strong> 的「Go to Disk Saver」看清理建议。</p><p><strong>未经确认它绝不擅自删除文件</strong>，拒绝清理现有文件就原样保留。</p><h2 id="本地网络出口-路由与访问私有网络" tabindex="-1">本地网络出口：路由与访问私有网络 <a class="header-anchor" href="#本地网络出口-路由与访问私有网络" aria-label="Permalink to &quot;本地网络出口：路由与访问私有网络&quot;">​</a></h2><p><img src="'+l+'" alt="本地网络出口：路由与访问私有网络" width="1600" height="1013" loading="lazy" decoding="async"></p><p>解决微信公众号、企业内网 IP 白名单或局域网访问，<strong>走本地设备中继流量就行</strong>。</p><h3 id="开启步骤" tabindex="-1">开启步骤 <a class="header-anchor" href="#开启步骤" aria-label="Permalink to &quot;开启步骤&quot;">​</a></h3><ol><li>按 <code>Cmd+,</code> 进设置，点 <strong>计算机</strong>。</li><li>在 <strong>你的计算机</strong> 找到当前电脑，打开 <strong>通过当前计算机路由流量</strong>。</li></ol><h3 id="限制与避坑" tabindex="-1">限制与避坑 <a class="header-anchor" href="#限制与避坑" aria-label="Permalink to &quot;限制与避坑&quot;">​</a></h3><ul><li>每次限单台。外部识别为本地 IP，Bot 也能直接访问局域网。</li><li><strong>仅对新请求生效</strong>，已有 TCP 长连接仍走原路线。</li><li>管理员若关 <code>Allow Local Egress Routing</code>，开关置灰提示 <code>Disabled by your admin. You can&#39;t turn this on.</code>，5 分钟内强制断开，见 <a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">设置和通知</a>。</li><li><code>Execution on this computer</code> 控制本地 Shell，默认逐条确认，<strong>切勿随意放开全自动</strong>。</li></ul><h2 id="重建、更新与终止-云电脑的生命周期" tabindex="-1">重建、更新与终止：云电脑的生命周期 <a class="header-anchor" href="#重建、更新与终止-云电脑的生命周期" aria-label="Permalink to &quot;重建、更新与终止：云电脑的生命周期&quot;">​</a></h2><p><img src="'+i+'" alt="重建、更新与终止：云电脑的生命周期" width="1600" height="1013" loading="lazy" decoding="async"></p><p>重构<strong>清空自装环境</strong>，保留磁盘与登录态。</p><p>见 <a href="https://cursor.com/cn/help/grok-bot/computer-recovery" target="_blank" rel="noreferrer">Grok Bot 计算机</a> 和 <a href="https://cursor.com/cn/docs/grok-bot/computers" target="_blank" rel="noreferrer">管理 Grok Bot 电脑</a>。</p><table tabindex="0"><thead><tr><th>操作</th><th>保留</th><th>清除与坑点</th></tr></thead><tbody><tr><td>软件更新</td><td>全部</td><td>无</td></tr><tr><td>更新/重建</td><td>磁盘与文件</td><td>清自装环境；重跑脚本</td></tr><tr><td>终止 VMs</td><td>磁盘</td><td>闲置 30 天关机丢进度</td></tr><tr><td>Recover/Reset</td><td>已存数据</td><td>中断任务，丢未存代码</td></tr></tbody></table><p>显示 <code>Reconnecting</code> 时<strong>别盲目 Reset</strong>，按顺序排查。</p><ol><li><strong>点 Retry</strong>。重连中磁盘完好，乱点破坏现场。</li><li><strong>彻底退出</strong>。macOS 需 <code>Cmd+Q</code> 退出再重启，别只点红叉。</li><li><strong>查更新</strong>。进「设置」&gt;「计算机」，Bot 空闲再更新。</li><li><strong>优先 Recover</strong>。弹出选项先选它，尽量存快照。</li><li><strong>最后 Reset</strong>。确认无未存代码且全失效再重置。</li></ol><h2 id="灾备流水线-服务总账与幂等恢复脚本" tabindex="-1">灾备流水线：服务总账与幂等恢复脚本 <a class="header-anchor" href="#灾备流水线-服务总账与幂等恢复脚本" aria-label="Permalink to &quot;灾备流水线：服务总账与幂等恢复脚本&quot;">​</a></h2><p><img src="'+p+`" alt="灾备流水线：服务总账与幂等恢复脚本" width="1600" height="1013" loading="lazy" decoding="async"></p><p>更新或重置会清空环境。铁柱AGI（@cgnot996）在 2026-10-10 提出方案，<strong>只备拉起方法，不存整机</strong>。</p><p>他用 5.1MB 私有仓库管 10 个 Bot 的 20 个服务（18 项必恢复，含 4 个常驻、14 个按需与 2 个密钥路径项），详见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Q6ZdwzjO5i6z0pkdMfyca8Cbnye" target="_blank" rel="noreferrer">教程</a>。</p><h3 id="规范结构与入账" tabindex="-1">规范结构与入账 <a class="header-anchor" href="#规范结构与入账" aria-label="Permalink to &quot;规范结构与入账&quot;">​</a></h3><p>仓库 <code>vm-services</code> 包含四部分。</p><ul><li><code>REGISTRY.md</code> 与 <code>registry.json</code>：总账及配置。</li><li><code>restore/restore-&lt;服务名&gt;.sh</code>：单服务脚本，<strong>必须幂等</strong>。</li><li><code>restore/restore-all.sh</code>：依序装库、CLI 并起后台服务，统计失败。</li><li><code>service-src/</code>：源码归档，排除 <code>.env</code>、日志与虚拟环境。</li></ul><p>新服务登记包含这几项。短 ID 与负责 Bot；代码及数据路径；安装方式（apt/pip/npm/Docker）与系统依赖；启动和检查命令（--version 或端口）；是否必恢复；密钥绝对路径（<strong>严禁记录明文</strong>）；扫码或 OAuth 等步骤。</p><h3 id="两套提示词" tabindex="-1">两套提示词 <a class="header-anchor" href="#两套提示词" aria-label="Permalink to &quot;两套提示词&quot;">​</a></h3><p>发给「虚拟机服务管家」Bot，其他 Bot 部署依此交差。</p><details class="details custom-block"><summary>部署与登记提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是「虚拟机服务管家」，只管一件事：记下这台虚拟机上部署过的所有第三方服务，并在电脑更新或换账号之后，按记录把它们原样恢复。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你维护的东西：</span></span>
<span class="line"><span>1. 一份登记总账，人和机器各读一份：REGISTRY.md（表格）和 registry.json（给脚本读）。</span></span>
<span class="line"><span>2. 每个服务一个恢复脚本 restore/restore-&lt;服务&gt;.sh，必须幂等，重复跑也不会出错。</span></span>
<span class="line"><span>3. 一个总入口 restore/restore-all.sh，按依赖顺序调用各个恢复脚本，最后汇总哪些失败了。</span></span>
<span class="line"><span>4. 一份源码备份 service-src/：各 Bot 自己写的服务代码和脚本，同步时排除密钥、日志、运行状态、虚拟环境和个人数据，并先扫一遍明文密钥，命中就停。</span></span>
<span class="line"><span>5. 以上全部跟着一个私有 Git 仓库存（「你的备份仓库地址」）。总账、恢复脚本、源码都在仓库里，密钥永远不进仓库。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>登记规则（其他 Bot 部署任何服务都必须来找你登记）：</span></span>
<span class="line"><span>每项必须包含：</span></span>
<span class="line"><span>- 名称和短 id、用途、负责的 Bot</span></span>
<span class="line"><span>- 路径：代码、配置、数据分别在哪</span></span>
<span class="line"><span>- 安装方式和依赖（apt / pip / npm / Docker / 系统定时任务）</span></span>
<span class="line"><span>- 启停命令、健康检查命令</span></span>
<span class="line"><span>- 更新后的恢复步骤，或者对应的恢复脚本</span></span>
<span class="line"><span>- 是否必恢复：是 / 否</span></span>
<span class="line"><span>- 密钥：只写存放路径，绝不写明文</span></span>
<span class="line"><span>- 需要真人完成的步骤（OAuth 登录、扫码、导入 cookie）单独标出来</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你的工作方式：</span></span>
<span class="line"><span>- 先弄清哪些会丢、哪些能留：电脑更新一般保留工作目录，但系统包、常驻进程、全局安装的命令行工具会丢；重置则什么都不留。所以要记的是“怎么重建”，不是去拷整台机器。</span></span>
<span class="line"><span>- 能从公开渠道重装的（apt、pip、npm、上游 Git 仓库）只记安装命令；自己写的代码必须进源码备份，否则重置后就找不回来。</span></span>
<span class="line"><span>- 收到登记先核对：路径是否真实存在、健康检查能不能过。登记写的和实际不一样时，以实际为准，并告诉负责的 Bot。</span></span>
<span class="line"><span>- 多个定时任务合并成一份 crontab 真源时，检查每一条是不是都在真源里，不在的要靠恢复脚本补回去。</span></span>
<span class="line"><span>- 故意停掉的服务要写清楚“为什么停、什么条件下重开”，免得被当成漏装。</span></span>
<span class="line"><span>- 只有主人说“电脑更新完了”才跑总恢复，不盲跑。跑完交验收：每项是成功、失败，还是要真人处理。</span></span>
<span class="line"><span>- 每次有服务新增、删除或源码大改，先重新同步源码备份，再把总账、脚本、源码一起提交推送到备份仓库。换账号或重置时，就靠这份备份把整套设定带走。</span></span>
<span class="line"><span>- 删掉的服务要彻底清除：总账只反映现在真实的状态。</span></span></code></pre></div></details><p>重置后配好 Git 凭证发给恢复 Bot。<strong>验收标准按清单汇报结果、用时与检查状态</strong>。</p><details class="details custom-block"><summary>重置后的一键恢复提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这台电脑刚重置过（或者是换了新账号），之前部署的服务都没了。请按我的备份把它们恢复到可用状态，规则如下。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>备份在哪：</span></span>
<span class="line"><span>- 备份仓库：&lt;你的备份仓库地址&gt;，分支 &lt;分支名&gt;</span></span>
<span class="line"><span>- 仓库里有：登记总账（REGISTRY.md 和 registry.json）、每个服务的恢复脚本（restore/）、自写服务的源码备份（service-src/）</span></span>
<span class="line"><span>- 仓库里没有密钥，这是故意的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按这个顺序做：</span></span>
<span class="line"><span>1. 把备份仓库拉到工作目录，先读总账，告诉我一共登记了几项、哪些标了「必恢复」、哪些只留密钥不用恢复。先列出来，不要动手。</span></span>
<span class="line"><span>2. 把自写服务的源码从 service-src/ 放回总账写的原位置。只补缺失的，已经存在的目录不要覆盖。</span></span>
<span class="line"><span>3. 按总账的依赖顺序逐项恢复：先装系统依赖（比如 cron、ffmpeg），再装命令行工具，最后拉起常驻服务和定时任务。每项都用它自己的恢复脚本，脚本要能重复跑。</span></span>
<span class="line"><span>4. 每装完一项就跑它登记的健康检查。失败了先看日志、试着修一次；修不好就记下原因，接着做下一项，不要卡住。</span></span>
<span class="line"><span>5. 把需要我本人做的事汇总成一张清单：要重新提供的密钥（只说放哪个路径、叫什么名字，别让我把密钥贴进聊天）、要重新登录授权的工具（OAuth、扫码、设备码）。然后一项一项带我做，每做完一项马上复查。</span></span>
<span class="line"><span>6. 故意暂停的任务保持暂停，总账里写了原因和重开条件的照办。别因为“看起来漏装了”就自作主张打开。</span></span>
<span class="line"><span>7. 最后交验收清单，每项一行：服务名、结果（成功 / 失败 / 等我处理）、健康检查输出摘要、花了多久。再告诉我总共用了多少时间、成功了几项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要做的事：</span></span>
<span class="line"><span>- 不要把任何密钥写进仓库、日志或聊天</span></span>
<span class="line"><span>- 不要跑总账没登记的安装</span></span>
<span class="line"><span>- 不要用“重置电脑”当修复手段</span></span>
<span class="line"><span>- 恢复完如果有任何改动（路径变了、版本升级了），更新总账，提交推回备份仓库</span></span></code></pre></div></details><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><h3 id="凭证与权限" tabindex="-1">凭证与权限 <a class="header-anchor" href="#凭证与权限" aria-label="Permalink to &quot;凭证与权限&quot;">​</a></h3><ul><li><strong>别在聊天框贴密钥</strong>：网页端手动输；CLI 的 Token 写入 <code>~/.env</code>，脚本读环境变量。</li><li><strong>Bot 间无隔离</strong>：共享 <code>/workspace</code> 与权限。敏感资产靠私有仓库和人工审批，多开没用。</li></ul><h3 id="协作与依赖" tabindex="-1">协作与依赖 <a class="header-anchor" href="#协作与依赖" aria-label="Permalink to &quot;协作与依赖&quot;">​</a></h3><ul><li><p><strong>交接须落盘</strong>：Bot 互不读会话。A 的结果存为 Markdown 或 JSON，光靠说 B 会幻觉。</p></li><li><p><strong>依赖不持久</strong>：更新、Recover 或 Reset 会清空 <code>apt install</code> 与 <code>npm install -g</code> 的内容，<code>node_modules</code> 和 <code>.venv</code> 也不备份。</p><p><strong>恢复脚本须包含</strong> <code>npm install</code> 与 <code>pip install -r requirements.txt</code>。</p></li></ul><h3 id="运维与网络" tabindex="-1">运维与网络 <a class="header-anchor" href="#运维与网络" aria-label="Permalink to &quot;运维与网络&quot;">​</a></h3><ul><li><strong>见 Reconnecting 别按 Reset</strong>：会丢未存盘改动并强行重建，<strong>先重试或重启客户端</strong>。</li><li><strong>定时任务集中管</strong>：crontab 须统一存入 Git 仓库维护。</li><li><strong>开本地路由须重启</strong>：开启「通过当前计算机路由流量」若 IP 没变，重启该进程。</li></ul><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li>Bot A 往 <code>/workspace/handoff/test.json</code> 写时间戳。<strong>Bot B 读取并准确说出</strong>即通畅。</li><li>在「设置」&gt;「计算机」开启「通过当前计算机路由流量」，终端跑 <code>curl -s https://api.ipify.org</code>。<strong>外网 IP 需与本地一致</strong>，非机房 IP。</li><li>让 Bot 打开 GitHub 登录页，<strong>必须在密码框前暂停并提示移交</strong>。手动登录后继续，确认日志无明文密码。</li><li>确认私有 Git 已提交 <code>REGISTRY.md</code>、<code>registry.json</code> 与脚本。在测试目录拉取并运行：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore/restore-all.sh</span></span></code></pre></div><p><strong>健康检查需全数通过</strong>，无冲突报错，总账服务正常监听。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档与知识库" tabindex="-1">官方文档与知识库 <a class="header-anchor" href="#官方文档与知识库" aria-label="Permalink to &quot;官方文档与知识库&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/computers" target="_blank" rel="noreferrer">管理 Grok Bot 电脑</a>：官方关于企业版多计算机批量重建、终止与 30 天闲置清理的完整规则。</li><li><a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">设置和通知</a>：官方关于桌面端设置、本地命令执行、流量中继路由与 Auto-review 模式的说明。</li><li><a href="https://cursor.com/cn/help/grok-bot/computer-recovery" target="_blank" rel="noreferrer">Grok Bot 计算机</a>：官方关于 Update、Recover、Reset 的区别与排错自查清单。</li></ul><h3 id="社区实战参考" tabindex="-1">社区实战参考 <a class="header-anchor" href="#社区实战参考" aria-label="Permalink to &quot;社区实战参考&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/KUggwkhqqiRyxZkwTLhcrCU2ncg" target="_blank" rel="noreferrer">《4.6 虚拟机、记忆与备份》</a>：详细拆解云电脑底层架构、上下文组织地图与多 Bot 文件协作。</li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Q6ZdwzjO5i6z0pkdMfyca8Cbnye" target="_blank" rel="noreferrer">《Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词）》</a>：社区作者铁柱AGI（@cgnot996）分享的虚拟机服务管家设计、总账登记表与一键恢复实战。</li></ul>`,86)])])}const q=s(c,[["render",d]]);export{f as __pageData,q as default};
